using System;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;
public static class B2Show {
 public static object Run(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var scene=SceneManager.GetActiveScene();var go=new GameObject("B2_TemporaryReviewView"){hideFlags=HideFlags.HideAndDontSave};try{go.transform.position=new Vector3(19,-32.35f,-9);go.transform.LookAt(new Vector3(19,-30.5f,2));var v=SceneView.lastActiveSceneView??EditorWindow.GetWindow<SceneView>();v.in2DMode=false;v.sceneLighting=true;v.AlignViewToObject(go.transform);v.Focus();v.Repaint();}finally{UnityEngine.Object.DestroyImmediate(go);}if(scene.isDirty)EditorSceneManager.OpenScene(scene.path);return new{scene=SceneManager.GetActiveScene().path,saved=!SceneManager.GetActiveScene().isDirty,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled};}
}
